 for(int n=1;n<=4;++n){mb::Binding b;b.source="synthetic-pico-source";b.device="HIL-SYNTH-OLD-0000"+std::to_string(n);b.tracker="slot-"+std::to_string(n);b.profile="synthetic-pico";b.inputSpace="hil-pico-space";b.inputRevision=7;b.worldSpace="synthetic-world";c.bindings[{b.source,b.device}]=b;mb::CapabilityProfile cp;cp.id="explicit-pico-c0-header";cp.provenance="Explicit c0f2f92 Header position/orientation/linear_velocity; synthetic provisioning";cp.inputDeclaration=cp.outputDeclaration={"position","orientation","linear_velocity"};c.contracts[{b.source,b.device}]=cp;}
